const skuList =
document.getElementById("skuList");

// LLENAR AUTOCOMPLETE

productos.forEach(producto=>{

    const option =
    document.createElement("option");

    option.value =
    producto.sku;

    option.label =
    producto.material;

    skuList.appendChild(option);

});

// CONVERTIR LETRA A MES

function obtenerMes(letra){

    const meses = {

        A:1,
        B:2,
        C:3,
        D:4,
        E:5,
        F:6,
        G:7,
        H:8,
        I:9,
        J:10,
        K:11,
        L:12
    };

    return meses[letra.toUpperCase()];
}

// CALCULAR VIDA

function calcularVida(){

    const sku =
    document.getElementById("skuInput")
    .value
    .trim();

    const lote =
    document.getElementById("lote")
    .value
    .trim();

    if(!sku || !lote){

        alert("Completa todos los campos");

        return;
    }

    const producto =
    productos.find(
        p => p.sku === sku
    );

    if(!producto){

        alert("SKU no encontrado");

        return;
    }

    if(!Number.isFinite(producto.vidaMaxima) || producto.vidaMaxima <= 0){
        alert("Este SKU no tiene una vida máxima válida confirmada. Consulta el catálogo antes de calcular.");
        return;
    }

    // D106

    const letraMes =
    lote.charAt(0);

    const dia =
    lote.substring(1,3);

    const anio =
    "202" + lote.charAt(3);

    const mes =
    obtenerMes(letraMes);

    if(!mes){

        alert("Lote inválido");

        return;
    }

    const fechaLote =
    new Date(anio, mes - 1, dia);

    const hoy =
    new Date();

    const diferenciaMs =
    hoy - fechaLote;

    const diasActuales =
    Math.floor(
        diferenciaMs /
        (1000 * 60 * 60 * 24)
    );

    const porcentaje =
    (
        diasActuales /
        producto.vidaMaxima
    ) * 100;

    let resultado = "";

    if(porcentaje > 0  && porcentaje< 45){

        resultado = "✔ DENTRO DE FRESCURA";

    }else if(porcentaje > 45  && porcentaje< 55){

        resultado = "⚠ VALIAR CON ENCARGADO DE FRESCURA";
    } else{
         resultado = "✖ RECHAZAR";
    }

    document.getElementById("resultado")
    .style.display = "block";

    document.getElementById("material")
    .textContent =
    producto.material;

    document.getElementById("fechaLote")
    .textContent =
    fechaLote.toLocaleDateString();

    document.getElementById("vidaMaxima")
    .textContent =
    producto.vidaMaxima;

    document.getElementById("diasActuales")
    .textContent =
    diasActuales;

    document.getElementById("porcentaje")
    .textContent =
    porcentaje.toFixed(2);

    const estatus =
    document.getElementById("estatus");

    estatus.textContent =
    resultado;

    estatus.classList.remove(
        "aceptar",
        "rechazar"
    );

    if(resultado === "✔ DENTRO DE FRESCURA"){

        estatus.classList.add(
            "aceptar"
        );

    }else if(resultado === "⚠ VALIAR CON ENCARGADO DE FRESCURA"){

        estatus.classList.add(
            "Validar"
        );

    } else {
        estatus.classList.add(
            "rechazar"
        );

    }
}
